import {makeScene2D, CubicBezier, Rect} from '@canvas-commons/2d';
import {waitFor, createSignal, createComputed} from '@canvas-commons/core';

export default makeScene2D(function* (view) {
  const progress = createSignal(0);

  const bezierElement = new CubicBezier({
    lineWidth: 6,
    stroke: 'lightgray',
    p0: [-300, -70],
    p1: [120, -120],
    p2: [-120, 120],
    p3: [300, 70],
  });

  const curvePoint = createComputed(() =>
    bezierElement.getPointAtPercentage(progress()),
  );

  const rectElement = new Rect({
    size: 25,
    fill: 'lightseagreen',
    position: () => curvePoint().position,
    rotation: () => curvePoint().tangent.degrees,
  });

  view.add([bezierElement, rectElement]);

  yield* progress(1, 2);
  yield* waitFor(0.5);
  yield* progress(0, 2);
  yield* waitFor(0.5);
});

